    solution: `function gcdOfStrings(str1, str2) {\n  if (str1 + str2 !== str2 + str1) return "";\n  const gcd = (a, b) => b === 0 ? a : gcd(b, a % b);\n  return str1.slice(0, gcd(str1.length, str2.length));\n}`,
