    solution: `function maxOperations(nums, k) {\n  nums.sort((a, b) => a - b);\n  let l = 0, r = nums.length - 1, count = 0;\n  while (l < r) {\n    const sum = nums[l] + nums[r];\n    if (sum === k) { count++; l++; r--; }\n    else if (sum < k) l++;\n    else r--;\n  }\n  return count;\n}`,
