    output: "Input: n = 3\nOutput: 5\n\nInput: n = 1\nOutput: 1",
    solution: `function numTilings(n) {\n  const MOD = 1e9 + 7;\n  if (n <= 2) return n;\n  if (n === 3) return 5;\n  let dp = [0, 1, 2, 5];\n  for (let i = 4; i <= n; i++) {\n    dp[i] = (2 * dp[i-1] + dp[i-3]) % MOD;\n  }\n  return dp[n];\n}`,
