      java: `class Solution {\n    public int numTilings(int n) {\n        int MOD = 1_000_000_007;\n        if (n <= 2) return n;\n        if (n == 3) return 5;\n        long[] dp = new long[n+1];\n        dp[1]=1; dp[2]=2; dp[3]=5;\n        for (int i = 4; i <= n; i++) dp[i] = (2*dp[i-1] + dp[i-3]) % MOD;\n        return (int)dp[n];\n    }\n}`,
