      java: `class Solution {\n    public int maxSubarraySumCircular(int[] nums) {\n        int maxSum=nums[0], minSum=nums[0], curMax=0, curMin=0, total=0;\n        for (int n : nums) {\n            curMax=Math.max(curMax+n,n); maxSum=Math.max(maxSum,curMax);\n            curMin=Math.min(curMin+n,n); minSum=Math.min(minSum,curMin);\n            total+=n;\n        }\n        return maxSum>0?Math.max(maxSum,total-minSum):maxSum;\n    }\n}`,
      javascript: `function maxSubarraySumCircular(nums) {\n  let maxSum=nums[0], minSum=nums[0], curMax=0, curMin=0, total=0;\n  for (const n of nums) {\n    curMax=Math.max(curMax+n,n); maxSum=Math.max(maxSum,curMax);\n    curMin=Math.min(curMin+n,n); minSum=Math.min(minSum,curMin);\n    total+=n;\n  }\n  return maxSum>0?Math.max(maxSum,total-minSum):maxSum;\n}`,
